// mirrored legs ride - THE ROUND-TRIP RECORD THE FAMILY HOLDS (the
// .186 word's own two never back-to-back the mirror beside - this
// book's own closer pair 385/386 back-to-back mirrored)
const roundTrips = []
for (let f = 350; f <= 386; f++) {
  if (P[f - 2] === P[f] && !(P[f - 1] === P[f - 2] || P[f] === P[f - 1])) roundTrips.push(f)
}
assert.deepEqual(roundTrips, [370, 379, 385, 386], 'the birth field holds the FOUR round trips - THE ROUND-TRIP RECORD THE FAMILY HOLDS')
assert.equal(roundTrips[3] - roundTrips[2], 1, 'the closer pair 385/386 back-to-back mirrored the record rides')
assert.equal(roundTrips[1] - roundTrips[0], 9, 'the 370/379 pair the spread holds')
for (const f of roundTrips) {
  assert.equal(Math.abs(P[f - 1] - P[f - 2]), Math.abs(P[f] - P[f - 1]), `the round trip F${f} the same size both legs the mirror rides`)
}
assert.equal(w(385), SWING + '0 -> 7 (+7) -> 0 (-7)' + SWING_TAIL, 'the closer\u2019s own first round trip the swing rides')
assert.equal(w(386), SWING + '7 -> 0 (-7) -> 7 (+7)' + SWING_TAIL, 'the closer\u2019s own second round trip the swing rides')

// THE TOP THE COUNT 18 - rode ONCE the face 360's own crest holds
