const steps = []
for (let f = 350; f <= 386; f++) { steps.push(P[f - 1] - P[f - 2]); steps.push(P[f] - P[f - 1]) }
assert.equal(Math.max(...steps), 16, 'the birth max rise +16 the bound holds')
assert.equal(Math.min(...steps), -16, 'the birth max fall -16 the bound holds')
