assert.equal(finalBankBudgetTrendRow({ back: { other: 1 }, prev: { finalBankBudgets: 2 }, cur: { finalBankBudgets: 3 } }), null)
assert.equal(finalBankBudgetTrendConsistent({ back: { finalBankBudgets: 0 }, prev: { finalBankBudgets: 0 }, cur: { finalBankBudgets: 0 } }), true)
assert.equal(finalBankBudgetTrendConsistent({ back: { finalBankBudgets: 5 }, prev: { finalBankBudgets: 9 }, cur: { finalBankBudgets: 2 }, spare: true }), true)
assert.equal(finalBankBudgetTrendConsistent(null), false)
assert.equal(finalBankBudgetTrendConsistent(undefined), false)
assert.equal(finalBankBudgetTrendConsistent('junk'), false)
assert.equal(finalBankBudgetTrendConsistent([]), false)
assert.equal(finalBankBudgetTrendConsistent({ back: { finalBankBudgets: 1 }, prev: { finalBankBudgets: 2 }, cur: { finalBankBudgets: NaN } }), false)

// THE CELL'S OWN READ - the real budget lines ride (every line the
// lane printed across the whole cache carried the flow-priced token,
// zero variants the field holds - every line the shape prints rides,
// no exclusion the shape needs)
assert.equal(finalBankBudgets([
  'F14 final bank budget: flow-priced 300676s (fleet bankable pocket 2088u (raw 2533u) at 0.0u/s needs 300676s) - the static 300s covered only the fast flows - clamped to 300s (the kill margin)',
  'F19 final bank budget: flow-priced 8078s (fleet bankable pocket 928u (raw 1259u) at 0.1u/s needs 8078s) - the static 248s covered only the fast flows - the tail burst (31s, 156u, 84% of the window\u2019s delta) is not a rate - priced at the ex-burst 0.1u/s - clamped to 300s (the kill margin)',
  'F10 final bank budget: flow-priced 1227s (fleet bankable pocket 488u (raw 760u) at 0.4u/s needs 1227s) - the static 248s covered only the fast flows - the tail burst (15s, 199u, 65% of the window\u2019s delta) is not a rate - priced at the ex-burst 0.4u/s - clamped to 300s (the kill margin)'
]), 3)
assert.equal(finalBankBudgets([
  'F5 final bank budget: flow-priced 1227s (fleet bankable pocket 488u (raw 760u) at 0.4u/s needs 1227s) - the static 248s covered only the fast flows - the tail burst (15s, 199u, 65% of the window\u2019s delta) is not a rate - priced at the ex-burst 0.4u/s - clamped to 300s (the kill margin)'
]), 1)
// THE FINAL BANK VERDICTS the bankdrain's own book prices never ride
// - the final bank lane's own seat (the lanes never merge)
assert.equal(finalBankBudgets(['F5 final bank: 0 (budget exhausted)']), 0)
assert.equal(finalBankBudgets(['F5 final bank: 3 stacks deposited']), 0)
assert.equal(finalBankBudgets(['F5 final bank: staggered +30s']), 0)
assert.equal(finalBankBudgets(['F5 final bank: +212']), 0)
// the final bank deferred night lines the bank pocket's own book
// prices never ride
assert.equal(finalBankBudgets(['F5 final bank deferred: night (tod=-1) - the pocket rides out the dark alive (the v0.976.60 night hold)']), 0)
// the bank raw colon lines the bank's own raw colon book prices
// never ride
assert.equal(finalBankBudgets(['F9 bank: chest unreachable (Took to long to decide path to goal!) (20 blocks from yard) - walking back']), 0)
assert.equal(finalBankBudgets(['F9 bank: yard walk arrived in 0s (1 attempt)']), 0)
assert.equal(finalBankBudgets(['F9 bank trip: deferred (rescue owns the bot - the rescuer holds the leash)']), 0)
// the bare skin never rides - no such emitter voice (the endphase's
// own final-bank budget lane prints the F-tagged form only)
assert.equal(finalBankBudgets(['final bank budget: flow-priced 1227s (fleet bankable pocket 488u (raw 760u) at 0.4u/s needs 1227s) - clamped to 300s (the kill margin)']), 0)
// the no-shape junk line never rides - the shape's own proof the RE
// demands
assert.equal(finalBankBudgets(['F6 final bank budgets: flow-priced 1227s']), 0)
assert.equal(finalBankBudgets(['F6 final bank budget: flow-priced1227s']), 0)
assert.equal(finalBankBudgets(['F6 final bank budget: 1227s']), 0)
assert.equal(finalBankBudgets(['final bank budget flow-priced 1227s']), 0)
assert.equal(finalBankBudgets(['F6 final bank budget:']), 0)

// the defensive reads
assert.equal(finalBankBudgets(null), 0)
assert.equal(finalBankBudgets(undefined), 0)
assert.equal(finalBankBudgets('junk'), 0)
assert.equal(finalBankBudgets(42), 0)
assert.equal(finalBankBudgets([null, 42, {}]), 0)

// THE ONE-PARSER RIDE - the fold rides the read's own arithmetic
const lines = [
  'F14 final bank budget: flow-priced 300676s (fleet bankable pocket 2088u (raw 2533u) at 0.0u/s needs 300676s) - the static 300s covered only the fast flows - clamped to 300s (the kill margin)',
  'F19 final bank budget: flow-priced 8078s (fleet bankable pocket 928u (raw 1259u) at 0.1u/s needs 8078s) - the static 248s covered only the fast flows - the tail burst (31s, 156u, 84% of the window\u2019s delta) is not a rate - priced at the ex-burst 0.1u/s - clamped to 300s (the kill margin)',
  'F10 final bank budget: flow-priced 1227s (fleet bankable pocket 488u (raw 760u) at 0.4u/s needs 1227s) - the static 248s covered only the fast flows - the tail burst (15s, 199u, 65% of the window\u2019s delta) is not a rate - priced at the ex-burst 0.4u/s - clamped to 300s (the kill margin)',
  'F5 final bank budget: flow-priced 1227s (fleet bankable pocket 488u (raw 760u) at 0.4u/s needs 1227s) - the static 248s covered only the fast flows - the tail burst (15s, 199u, 65% of the window\u2019s delta) is not a rate - priced at the ex-burst 0.4u/s - clamped to 300s (the kill margin)',
  'F9 final bank budget: flow-priced 900s (fleet bankable pocket 300u (raw 500u) at 0.3u/s needs 900s) - the static 248s covered only the fast flows - clamped to 300s (the kill margin)'
]
assert.equal(finalBankBudgets(lines), 5)
const fold = { back: { finalBankBudgets: finalBankBudgets(lines) }, prev: { finalBankBudgets: 1 }, cur: { finalBankBudgets: 0 } }
assert.equal(finalBankBudgetTrendRow(fold), FADE + '5 -> 1 (-4) -> 0 (-1)' + FADE_TAIL)

console.log('finalbankbudgettrend.test: all pins green')
